def rects(I, lc):
    h,w=len(I),len(I[0]); res=[]
    for r1 in range(h):
        for r2 in range(r1+2,h):
            for c1 in range(w):
                for c2 in range(c1+2,w):
                    ok=all(I[r1][c]==lc and I[r2][c]==lc for c in range(c1,c2+1)) and \
                       all(I[r][c1]==lc and I[r][c2]==lc for r in range(r1,r2+1))
                    if ok: res.append((r1,r2,c1,c2))
    return res
def check(I,O,name):
    from collections import Counter
    cnt=Counter(x for row in I for x in row)
    bg=cnt.most_common(1)[0][0]; lc=[c for c in cnt if c!=bg][0]
    print(name,'bg',bg,'line',lc,'rects:',rects(I,lc))
    exp=[[O[r][c] for c in range(len(I[0]))] for r in range(len(I))]
    for (r1,r2,c1,c2) in rects(I,lc):
        for r in range(r1+1,r2):
            for c in range(c1+1,c2):
                exp[r][c]=4
    print('match:',exp==O)
